--
-- Table structure for table `vehicle`
--

DROP TABLE IF EXISTS `vehicle`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `vehicle` (
  `vehicle_id` int NOT NULL AUTO_INCREMENT,
  `owner_id` int NOT NULL,
  `vehicle_type_id` int NOT NULL,
  `fuel_type_id` int NOT NULL,
  `ac` bit(1) DEFAULT NULL,
  `status` enum('ACTIVE','BLOCKED','MAINTENANCE') NOT NULL DEFAULT 'ACTIVE',
  `vehicle_number` varchar(255) NOT NULL,
  `vehicle_rc_number` varchar(255) NOT NULL,
  `description` varchar(255) DEFAULT NULL,
  `model_id` int NOT NULL,
  PRIMARY KEY (`vehicle_id`),
  UNIQUE KEY `vehicle_number_UNIQUE` (`vehicle_number`),
  UNIQUE KEY `vehicle_rc_number_UNIQUE` (`vehicle_rc_number`),
  UNIQUE KEY `UKd5rc6b0dnypuf0pxvr25mgfvt` (`vehicle_number`),
  UNIQUE KEY `UKox19ftj97qu595v9d0ynr4mdp` (`vehicle_rc_number`),
  KEY `owner_id_fk_idx` (`owner_id`),
  KEY `vehicle_type_id_fk_idx` (`vehicle_type_id`),
  KEY `model_id_fk_idx` (`model_id`),
  KEY `fuel_id_fk_idx` (`fuel_type_id`),
  KEY `idx_vehicle_model_id` (`model_id`),
  CONSTRAINT `fk_vehicle_fuel_type` FOREIGN KEY (`fuel_type_id`) REFERENCES `fuel_type` (`fuel_id`) ON DELETE RESTRICT ON UPDATE CASCADE,
  CONSTRAINT `fk_vehicle_model` FOREIGN KEY (`model_id`) REFERENCES `models` (`model_id`) ON DELETE RESTRICT ON UPDATE CASCADE,
  CONSTRAINT `owner_id_fk` FOREIGN KEY (`owner_id`) REFERENCES `user` (`user_id`),
  CONSTRAINT `vehicle_type_id_fk` FOREIGN KEY (`vehicle_type_id`) REFERENCES `vehicle_type` (`vehicle_type_id`)
) ENGINE=InnoDB AUTO_INCREMENT=15 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

--
-- Dumping data for table `vehicle`
--

LOCK TABLES `vehicle` WRITE;
/*!40000 ALTER TABLE `vehicle` DISABLE KEYS */;
